body {
  font-family: var(--font-base);
  background-color: var(--color-fondo-claro);
  color: var(--color-texto-principal);
  line-height: 1.6;
  /* Aplicando el reset de márgenes y padding que solicitaste */
  margin: 0;
  padding: 0;
}

p {
  margin-bottom: 1.5rem;
}

/* SOLUCIÓN AL ERROR DE API OBSOLETA: Definir tamaños de fuente explícitos */

h1 {
  font-family: var(--font-titulos);
  margin-top: 2.5rem;
  margin-bottom: 1.5rem;
  line-height: 1.1;
  font-weight: 700;
  font-size: 3rem;
  /* Equivalente a text-5xl */
}

h2 {
  font-family: var(--font-titulos);
  font-size: 2rem;
  font-weight: 700;
  line-height: 1.2;
  margin-top: 2rem;
  margin-bottom: 1rem;
}

h3 {
  font-family: var(--font-titulos);
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.3;
  margin-top: 1.5rem;
  margin-bottom: 0.75rem;
}

h4, .logo-text {
  font-family: var(--font-titulos);
  margin-top: 1.5rem;
  margin-bottom: 0.5rem;
}

ul, ol {
  margin-top: 1rem;
  margin-bottom: 1.5rem;
  padding-left: 1.5rem;
}

li {
  margin-bottom: 0.5rem;
}

table {
  width: 100%;
  margin: 1.5rem 0 2rem;
  border-collapse: collapse;
}

blockquote {
  margin: 2rem 0;
  padding: 1rem 1.5rem;
  border-left: 4px solid var(--color-turquesa);
  background-color: rgba(0, 123, 255, 0.05);
}

/* Clases de texto y gradientes */

.subtitle {
  font-family: var(--font-subtitulo);
  /* Le añadimos un tamaño por defecto para mejorar el uso como subtítulo */
  font-size: 1.25rem;
  font-weight: 400;
}

.text-turquesa {
  color: var(--color-turquesa);
}

.text-morado-neon {
  color: var(--color-morado-neon);
}

.text-verde-neon {
  color: var(--color-verde-neon);
}

/* Corregir el error de text-fill-color */

.brand-gradient-text-404 {
  background: linear-gradient(90deg, var(--color-turquesa), var(--color-morado-neon));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.brand-gradient-text {
  background: linear-gradient(to right, var(--color-turquesa), var(--color-morado-neon));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.hero-dark-tv .subtitle {
  color: var(--color-gris-claro);
}

/* Línea divisora de marca */

.container {
  width: 100%;
}

@media (min-width: 640px) {
  .container {
    max-width: 640px;
  }
}

@media (min-width: 768px) {
  .container {
    max-width: 768px;
  }
}

@media (min-width: 1024px) {
  .container {
    max-width: 1024px;
  }
}

@media (min-width: 1280px) {
  .container {
    max-width: 1280px;
  }
}

@media (min-width: 1536px) {
  .container {
    max-width: 1536px;
  }
}

/* CTA Principal: Verde Neón */

.cta-neon-green {
  background-color: var(--color-verde-neon);
  color: var(--color-negro-profundo);
  font-family: var(--font-titulos);
  font-weight: 700;
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  box-shadow: 0 0 10px var(--color-verde-neon), 0 0 20px rgba(0, 255, 153, 0.5);
  transition: all 0.3s ease-in-out;
}

.cta-neon-green:hover {
  box-shadow: 0 0 15px var(--color-verde-neon), 0 0 30px rgba(0, 255, 153, 0.7);
  transform: translateY(-2px);
}

/* CTA Secundaria: Morado Neón */

.cta-secondary-purple {
  background-color: transparent;
  color: var(--color-morado-neon);
  border: 2px solid var(--color-morado-neon);
  font-family: var(--font-subtitulo);
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  transition: all 0.3s ease-in-out;
}

.cta-secondary-purple:hover {
  background-color: var(--color-morado-neon);
  color: var(--color-negro-profundo);
}

/* ADMONITION TIP (Soluciones o Consejos) */

.admonition-tip {
  padding: 1rem 1.5rem;
  margin: 1.5rem 0;
  border-left: 5px solid var(--color-turquesa);
  background-color: rgba(0, 123, 255, 0.1);
  /* Fondo Turquesa semitransparente */
  border-radius: 0.25rem;
  color: var(--color-gris-claro);
  /* Texto gris claro (para modo oscuro) */
}

.admonition-tip strong {
  color: var(--color-turquesa);
  font-family: var(--font-titulos);
  font-weight: 700;
}

/* ADMONITION WARNING (Errores o Advertencias) */

.admonition-warning {
  padding: 1rem 1.5rem;
  margin: 1.5rem 0;
  border-left: 5px solid var(--color-morado-neon);
  background-color: rgba(157, 78, 221, 0.1);
  /* Fondo Morado semitransparente */
  border-radius: 0.25rem;
  color: var(--color-gris-claro);
}

.admonition-warning strong {
  color: var(--color-morado-neon);
  font-family: var(--font-titulos);
  font-weight: 700;
}

/* ENLACES DEL FOOTER */

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.125rem;
  /* Reducido aún más */
}

.footer-links li {
  display: flex;
  align-items: center;
}

.footer-links li a {
  color: var(--color-gris-claro);
  opacity: 0.7;
  padding: 0.125rem 0.25rem;
  border-radius: 3px;
  transition: all 0.3s ease;
  text-decoration: none;
  font-size: 0.75rem;
  white-space: nowrap;
}

.footer-links li a:hover {
  opacity: 1;
  color: var(--color-turquesa);
  background-color: rgba(0, 123, 255, 0.1);
  transform: translateY(-1px);
}

.footer-links li::after {
  content: '•';
  margin: 0 0.125rem;
  color: var(--color-morado-neon);
  opacity: 0.3;
  font-size: 0.625rem;
}

.footer-links li:last-child::after {
  display: none;
}

/* VIDEO RESPONSIVE */

.video-responsive {
  position: relative;
  padding-bottom: 56.25%;
  height: 0;
  overflow: hidden;
  margin-bottom: 1.5rem;
  border-radius: 12px;
  box-shadow: 0 0 20px rgba(0, 123, 255, 0.2);
}

.video-responsive iframe,
  .video-responsive object,
  .video-responsive embed {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

